-- ----------------------------
-- Table structure for t_sys_group_quick_config
-- ----------------------------
DROP TABLE IF EXISTS `t_sys_group_quick_config`;
CREATE TABLE `t_sys_group_quick_config`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '关联ID（主键，自增数值类型）',
  `group_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '小组ID（关联t_sys_group表主键）',
  `quick_config_ids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '快捷配置ID列表（逗号分隔，如：1,2,3）',
  `create_user` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建人',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_user` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新人',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint(1) NULL DEFAULT 0 COMMENT '逻辑删除标记（0=未删除，1=已删除）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_group_id`(`group_id`) USING BTREE COMMENT '小组ID唯一索引（一个小组只存一条记录）',
  INDEX `idx_create_time`(`create_time`) USING BTREE COMMENT '创建时间索引',
  INDEX `idx_update_time`(`update_time`) USING BTREE COMMENT '更新时间索引'
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '小组-快捷配置关联表' ROW_FORMAT = DYNAMIC;

