-- ----------------------------
-- Table structure for t_sys_quick_config
-- ----------------------------
DROP TABLE IF EXISTS `t_sys_quick_config`;
CREATE TABLE `t_sys_quick_config`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '快捷配置名称',
  `parent_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '父级ID（0为一级配置）',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `create_user` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `update_user` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `perm_ids` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '快捷配置ids',
  `quick_config_type` int(5) NULL DEFAULT NULL COMMENT '0-普通，1-GMP',
  `perm_ids_have` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '快捷配置ids拥有的',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_parent_id`(`parent_id`) USING BTREE COMMENT '父级ID索引'
) ENGINE = InnoDB AUTO_INCREMENT = 60 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '快捷配置表' ROW_FORMAT = DYNAMIC;

